GimCorpus.put(465,0,[[1,7,"אין משביעין וכו' עד וכן כל כיוצא בזה. א\"א בזה איני מודה לו כי היא טענת ברי ועל זו אמר ר\"א בן יעקב פעמים שאדם נשבע על טענת עצמו שהעמיד אותה בבא בטענת עצמו והוא שאמר כך צוה לי אבא שאם אמר ברי לי שאני יודע על זה אמרו מה לי הוא מה לי אביו ואפילו לרבנן עכ\"ל:",1,0],[1,8,"כור חטים יש לי בידך וכו' עד וכן כל כיוצא בזה. א\"א זה אינו שאינו משלם שעורים והיינו דרבה בר נתן אלא א\"כ תפס ואיכא דדחו לה דכיון דהאידנא איכא שבועת היסת אי אשתבע דלא ידענא אי חטים הוו או שעורים הוו הא אודי הודאה גמורה דאית ליה כל דהוא ולא דחייה הוא הילכך משלם ויש לו פנים אבל הוא היה צריך לגלות עכ\"ל:",1,0],[1,13,"מי שנתחייב שבועה וכו' עד השבע והפטר. א\"א ואם זה שנתחייב היסת ורואה שמגלגלין עליו הרבה והפך השבועה אם נאמר כבר פטר עצמו מן השבועה או נאמר לו או השבע לו על הכל או תהפך עליו את הכל שישבע ויטול שהרי אתה חייב לו שבועת היסת אף על הגלגולים כמו על הטענה הראשונה. זה המחבר האריך וקיצר ואני רואה כי זה הוא הדין או ישבע על הכל או יהפך על הכל וישבע זה ויטול ולא יפטר בהפוכו מן הגלגולים ואם אמר הנתבע על הגלגולין אני נשבע ונפטר ועל הטענה הראשונה השבע וטול הרשות בידו עכ\"ל:",1,0],[1,16,"אתה חבלת וכו' עד משלם שבת ורפוי ובשת. א\"א איני מוצא קנס בחבלות ואם מפני שאין דנין חבלות בבבל גם שבת ורפוי ובשת אין דנין ועוד שהרי בית דין מנדין עד שיפייס בעל דינו עכ\"ל:",1,0],[2,5,"וכן פוגם שטרו וכו' עד ויפטר מן השטר. א\"א איני מודה בזה אלא שנוטל בלא שבועה שאין פוסלין שטר מקויים מפני שבועה דרבנן ואם תאמר הא דרב ושמואל היא אמרינן הבו דלא לוסיף עלה עכ\"ל:",1,0],[3,7,"הורו רבותי שהנשבעין וכו' עד ישבע מספק. א\"א ומה יעשה השכיר העני שהשכיר עצמו במעה או בפונדיון ילך בפחי נפש. אבל הדמיון שדימה והלמוד שלמד מן הנשבעין בטענת ספק שהצריכו להם כפירת שתי כסף אינו דמיון כלל שזה נשבע להפטר ועל כרחו הוא נשבע וזה שנשבע ליטול מדעתו הוא נשבע כדי ליטול ואפילו על פרוטה ואולי אפילו היה שכרו פחות מפרוטה עכ\"ל:",1,0],[3,14,"מנה לי אצלך וכו' עד ולזה דעתי נוטה. א\"א ואני מורה ובא שאם טענו מנה מלוה ומנה פקדון והודה באחד וכפר באחד אין זה מודה במקצת הטענה שהלואה ופקדון שתי טענות הן ויש בידי ראיה על זה וה\"ה שאין בזה מקצת הודאה עכ\"ל:",1,0],[4,5,"וכן האומר לחבירו וכו' עד משבועת היסת. א\"א אני אומר שזה מחלוקת ראב\"י וחכמים ופסק הרב שהלכה כמותו עכ\"ל:",1,0],[4,6,"מנה לי בידך על וכו' עד שהודה בהם. א\"א ואם שוה החמשים מה ישבע הילך הוא עכ\"ל:",1,0],[4,6,"היה המשכון שוה וכו' עד על העשרים שכפר בהם. א\"א אף זה הילך הוא עכ\"ל:",2,0],[4,8,"לפיכך שטר שיש בו עד וכו' עד ואינו יכול לישבע ומשלם. א\"א משלים הוא ממשל ולמה לא יכחיש העד מכל וכל בשבועתו שפרע ואולי על דרך שכתב במקום אחר שטען תחלה בב\"ד להד\"מ והוציא עליו שטר זה שמכחישו בהלואה ואח\"כ אמר לויתי ופרעתי והיה לו להזהר בדבריו עכ\"ל:",1,0],[5,2,"וכן החופר בשדה וכו' עד הרי זה נשבע היסת על הכל. א\"א נראין דברים שתבעו למלאות החפירות ולהשוות החצירות אבל אם תבעו לשלם פחתו ה\"ה כשאר תביעת ממון וכמי שאמר לו חבלת בי שתים והוא אומר לא חבלתי אלא אחת עכ\"ל:",1,0],[5,4,"טענו ענבים וכו' עד ואין נשבעין עליהן וכו'. א\"א המחבר פוסק כרבי מאיר והרב פוסק כחכמים ואולי מפני מה שאמרו בכתובות סוף סוף כל העומד לגדור כגדור דמי והרב ז\"ל הלא ראה כל זה ואפשר שאין למדין שבועה לשאר דברים שהרי עבדים של יתומים נדונין כמטלטלין ולענין שבועה אין נשבעין עליהן עכ\"ל:",1,0],[5,6,"שטר מסרתי לך וכו' עד כמו שבארנו בהלכות חובל. א\"א תימה גדול הוא זה ואולי ברשותו הוא וכופר הוא בו ואם פטרוהו משבועת התורה משבועת פשיעה ומשבועה שאינה ברשותו לא פטרוהו עכ\"ל:",1,0],[5,9,"וכן אם הודה שהיה וכו' עד טענת שמא. א\"א נראין הדברים שנמסר החפץ לידו לשמירה מחיי אביו וכן השותף שהיה מחיי אביו והאפוטרופוס שמינוהו בית דין ומסתלק כשהוא קטן וזה אינו מן המנין שבית דין משביעין אותו עכ\"ל:",1,0],[6,3,"מנה הלויתיך וכו' עד שהרי הוחזק כפרן. א\"א אין צורך לזה הטעם עכ\"ל:",1,0],[6,5,"תן לי מנה שהלויתיך וכו' עד שפרעו. א\"א לאו דוקא אומר בפני פלוני ופלוני שזה לשון המדבר בהווה וזה לשון המדבר על עיקר הטענה ואין כאן חכמה עכ\"ל:",1,0],[6,7,"מעשה באחד שהיו וכו' עד ישבע היסת ויפטר. א\"א אין זה לפי הגמרא עכ\"ל:",1,0],[7,1,"טען כשבאו וכו' עד ונשבע היסת. א\"א דבריו חלושין מאד וסוף דבריו אינן משוים עם דברי הרב שכתב בסוף גט פשוט עכ\"ל:",1,0],[8,7,"מי שהיו וכו' עד שאדם עשוי למכור את כליו. א\"א לא ידעתי למה אם בשביל שטוענין ללוקח הלא הראשון שזה בא מכחו לא היה יכול לטעון ועוד הרי לא טען רבא ליורש בספרא דאגדתא עכ\"ל:",1,0],[8,10,"ראיה לדברינו וכו' עד סוף הפרק. א\"א אחר כל ההתראות והאזהרות האלה אשר התרה זה המחבר ואשר שם לרבים וגדולים טועים חזר הדין לכל דבר שאין כל אדם מקפיד עליו מלהשאילו או מפני בלאותו הרי הוא מדברים שאינם עשויין להשאיל ולהשכיר:",1,0],[9,5,"וכבר בארנו שיש מי שהורה וכו' עד ואין דעתי נוטה לזה. א\"א חיי ראשי אני איני אומר כן אלא כל נוטל נשבע בנקיטת חפץ ואפילו דברים הראויים להשאיל ולהשכיר אין מוציאין אלא בשבועה בנקיטת חפץ חוץ מראוהו שהטמין כליו תחת כנפיו ויצא בענין שנאמר בו שאינו נאמן לומר לקוחים הם בידי הואיל והעדים מעידים על הענין ההוא עכ\"ל:",1,0],[9,6,"מי שלקח קורדום וכו' עד הרי הוא כשאר מטלטלין. א\"א אנו מפרשים ואגדריה לדקלא פלניא בלקיטת הפירות כמו הגודר בתמרים ולקט הפירות והלך לו עכ\"ל:",1,0],[9,12,"באו שניהם אדוקין וכו' עד חולקין. א\"א אין טעם לזה עכ\"ל:",1,0],[12,2,"אפילו באו עדים וכו' עד כדי שיעידו לו. א\"א ונתננו לו השכר עכ\"ל:",1,0],[12,3,"בד\"א בחצרות וכו' עד הרי זה חזקה. א\"א אין דרך הגמרא כן דלרבויי מפוזרות קאמר ולא לרבויי מקוטעות עכ\"ל:",1,0],[12,12,"אכלה ערלה שביעית וכו' עד הרי זו חזקה. א\"א שבוש הוא ולא אמרו אלא שאכילת עצים שמה אכילה הואיל וליכא פירי אחריני עכ\"ל:",1,0],[12,20,"במה דברים אמורים בשאכל וכו' עד אף על פי שלא אסף כל פירותיה. א\"א דעת אחרת היה לו כי ראה בגמ' והוא דבזו בזויי וסבר כי הוא לשון בזה ושלל וטעה כי הוא כמו בזעיה בזועי והוא לשון פזור שאכל שלשה מכאן ושלשה מכאן ומכאן הוציאו המפרשים זה הפזור שכתב הוא עכ\"ל:",1,0],[14,5,"העכו\"ם אפילו אכלה כמה שנים וכו' עד ואין אכילתו ראיה. א\"א יש כאן שבוש ואומר אני שאם מכרה לישראל שישבע היסת אע\"פ שבא מחמת העכו\"ם עכ\"ל:",1,0],[14,7,"אין מחזיקין בנכסי קטן וכו' עד אחר שהגדיל. א\"א אינו כן אלא אפילו אכלה שלש שנים אחר שהגדיל אינה חזקה וכן נראה מן הגמרא עכ\"ל:",1,0],[14,8,"מי שהחזיק בנכסי קטן וכו' עד ותחזור ליתומים. א\"א נראה מדבריו דמעשה דרבה בר שרשום מוקי לה בשאינה ידועה שהיתה של אביהן ואם כן למה ליה למימר מגו דאי בעי אמר לקוחה היא בידו לימא דאי בעי אמר דידי היא ועוד משום קלא מבטלין מגו וחזקה דממונא ואיהו הוה מוחזק ואבוהון דיתמי לא הוה מוחזק אלא ודאי בחזקת אבוהון הות מיהו כיון דאכלה שני חזקה בחיי אבוהון בלא מחאה איכא מגו ואי לאו קלא הוה מהימן במגו והשתא דאיכא קלא לא אמרינן ומוקמי ארעא בחזקת אבהתא והאי דינא דקושטא עכ\"ל:",1,0],[14,9,"אכלה שני חזקה בחיי אביהם וכו' עד מתוך שיכול לומר שלי היא. א\"א נראה מדבריו אפילו יצא עליו קול שהיא של יתומים וזהו טעות גדולה דאיהי היא ועוד אני אומר שלא יועיל מגו לגבות לכתחלה בלא שבועה מידי דהוה אנשבע על המשכון שאמרו הגאונים שהוא נשבע ונוטל ורבה בר שרשום דקא בעי למפטר נפשיה משבועה אחר אכילה קאמר בין תבין עכ\"ל:",1,0]]);
